#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str

def solve(N: int, W: "Tuple[int, int]"):
    W = sorted(sorted(W, key=lambda work: work[0], reverse=True), key=lambda work: work[1])
    t = 0
    for i in range(N):
        t += W[i][0]
        if t > W[i][1]:
            return NO
    return YES


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    W = [(int(), int())] * (N)  # type: "Tuple[int, int]"
    for i in range(N):
        a = int(next(tokens))
        b = int(next(tokens))
        W[i] = (a, b)
    print(solve(N, W))

if __name__ == '__main__':
    main()
